SELECT data ->> '$.commit.collection' AS event, count(*) AS count FROM bluesky GROUP BY event ORDER BY count DESC;
SELECT data ->> '$.commit.collection' AS event, count(*) AS count, count(DISTINCT data ->> '$.did') AS users FROM bluesky WHERE data ->> '$.kind' = 'commit' AND data ->> '$.commit.operation' = 'create' GROUP BY event ORDER BY count DESC;
SELECT event, CAST(strftime('%H', time_us / 1000000, 'unixepoch') AS INTEGER) AS hour_of_day, count(*) AS count FROM (SELECT data ->> '$.commit.collection' AS event, data ->> '$.time_us' AS time_us FROM bluesky WHERE data ->> '$.kind' = 'commit' AND data ->> '$.commit.operation' = 'create' AND data ->> '$.commit.collection' IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') LIMIT -1) GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
SELECT user_id, strftime('%Y-%m-%d %H:%M:%f', MIN(time_us) / 1000000.0, 'unixepoch') AS first_post_date FROM (SELECT data ->> '$.did' AS user_id, data ->> '$.time_us' AS time_us FROM bluesky WHERE data ->> '$.kind' = 'commit' AND data ->> '$.commit.operation' = 'create' AND data ->> '$.commit.collection' = 'app.bsky.feed.post' LIMIT -1) GROUP BY user_id ORDER BY MIN(time_us) ASC LIMIT 3;
SELECT user_id, (MAX(time_us) - MIN(time_us)) / 1000 AS activity_span FROM (SELECT data ->> '$.did' AS user_id, data ->> '$.time_us' AS time_us FROM bluesky WHERE data ->> '$.kind' = 'commit' AND data ->> '$.commit.operation' = 'create' AND data ->> '$.commit.collection' = 'app.bsky.feed.post' LIMIT -1) GROUP BY user_id ORDER BY activity_span DESC LIMIT 3;
